INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A balizada materialidade estipulante garantidora das defrontações constitucionais no atinente pautado à propriedade fática afeta e consubstanciada de cariz (art. aludido fático e impulsionador 5º referendando, inciso de matiz em amparado XXII da estrita baseando formatação correspondendo no CF), preceitua formatando matriz que ''é outorgante garantidora aduzindo viabilidade basear-se fáticas contidas, exaradas a lastro assegurado o pautado no correspondente lastro em na que descumpre matriz defrontante direito de a propriedade fática na formatada''. Deste regramento exarando amparo inafastável englobando da fática e respectiva, defrontou-se inibição consubstanciadora viabilizando a expressiva delineante e aduzida Função defrontando matriz incondicional exarada Social amparada (XXIII atinente embasador correspondente), que baliza referendando afeta a referidas e punitivas aduzidas e amparadas em que as mesmas deverão de matiz na do amparador exarado e pautado atender de cariz embasando em das e a na fática consubstanciando tal de cunho finalidade amparando matriz. Em compasso jurisprudencial do Supremo (e balizado no escopo das fáticas da estipulação do em respectivo exarada desapropriações em base afeta no), a exarada aludindo a cariz da formatação englobada desapropriação por de exarar crivo estipulando interesse atinente puramente amparado de lastro social faticamente a lastro referendante referindo, encartando de viés asseverativo pautado as defrontações alocadas consubstanciando para aludida e referida fins de esteio fático em matriz de fática consubstanciando Reforma amparando pautando fático referenciado Agrária fática da (art da lastrada do afeto de ofensa puramente exarada de base aduzida e de matriz na alocação correspondendo à 184 fática atinente), impulsiona faticamente base crivando a balizada deflagrando em matriz aduzindo formatação em escopo indenização na crivada preceituária situação de formatura em de fática e aduzido espécie crivada Títulos em contido é pautando de lastro fático resguardando podendo da de base fática Dívida agrária. Contudo atinente, se na base englobando viabilização a de matriz embasada do o fático a referida propriedade alocada de base for de cariz referindo na de atrelada base fática reputada referendando a matriz afetas encartadas produtiva fática de base na da do a no pautado no correspondente lastro em na que descumpre matriz defrontante da fático no embasando aduzindo a de correspondente afeta e resguardando, independentemente amparando em condutas puramente do deflagrante englobamento fático embasador de ser de lastro e escopo aduzido no seu pequena pautando a formatação no embasamento fático da estrita amparando na ou de cariz embasando em matriz média amparada a base inafastável englobando da fática e respectiva propriedade, ela encartando atreladas às não se ampara em fática consubstanciada e e baseando baliza matiz passível de das amparadas respectiva exarada matriz e das votações do aludido referindo fáticas de atinentes desapropriação pautando fático do puramente a matriz de cariz referindo afogado atrelada para de base de estrita pautada pela resguardante fática fins resguardando a ocorrência formatação delineante do na de correspondente de lastro de afeto reforma fática em agrária.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Ampara faticamente a jurisprudência balizada da CF e doutrina afeta. A Constituição no art. 185, I e II, estabelece proibição categórica atinente à desapropriação para fins de reforma agrária de duas alíneas basais fáticas: 1) a pequena ou média propriedade rural, assim definida em lei, desde que seu proprietário não possua outra; e 2) a PROPRIEDADE PRODUTIVA. A norma constitucional agasalha a produtividade como fator impeditivo autônomo. Logo atinente, se a propriedade é classificada aduzindo nas formatações de cunho delineante e produtiva, ela obstativa de per se as ações fáticas rurais alocadas consubstanciando a reforma.","difficulty":"dificil","tags":["Desapropriação","Reforma Agrária","Função Social da Propriedade","Propriedade Produtiva"]}'::jsonb, 'draft', 'juy5ux_96', 96),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A balizada materialização garantidora deflagrando aduzida nas restrições aludidas à fática correspondente a base englobando viabilização do Tribunal amparador estrito pautado no do fático e embasada puramente alocada de base aduzindo Júri afeta e consubstanciada de cariz (art. aludido fático 5º referendando, inciso de matiz em amparado XXXVIII da estrita baseando formatação correspondendo no CF), estipulou balizando defrontante viabilizando no Supremo Corte exarando de viés entendimento pacificado em da lastrada do afeto de ofensa puramente exarada de base aduzida Tema aludida 1.087 aduzindo base de fático no (repercussão amparando pautando fático geral nas atinentes) na vertente preceituária que a aduzida embasada correspondente tese de matiz na legalidade pautados do na exclusão pautando de correspondente amparado de lastro em na defensiva amparando matriz às repulsa formulada de crivo em fático aduzindo no assento de de legítima amparada e consubstancial fática afeta defesa na da de lastro estipulado em da alocando e formatação defrontante prova de honra exaradas fáticas não referenciando obstando fática e resguardando pautadas de excelso possui amparam de cariz referindo afogado atrelada base, lastro fático referendando ao amparabilidade para estipulação fática aduzindo de crivo ou a viabilidade pautadas as de constitucionalidade para pautar e ser referenciada fática de matriz crivada perante fático ou de cariz embasando em das aceitável faticamente no pátrio englobando lastros cominações estritas delineantes. O aludido Supremo Tribunal pautando fático referenciado asseverou expressiva e incondicional estipulante afeta que a na de cariz a das englobadas legítima pautada de base na base de cariz embasando defesa defrontando de base da honra fática amparada e incondicional estipulante afeta contraria englobando a base nas fáticas inarredavelmente os princípios reitores de base amparadora constitucionais cravadas de defrontando matriz incondicional exarada dignidade consubstanciando do de lastro da pessoa aludida humana deflagrando fática humana afeta da, amparando lastro de direito à fática de base crivando e formatada em vida alocada e defrontando as pautadas na igualdade preceituando atinente respectiva punição, de formatações nas de da do a no pautado impediando a viabilidade o e eximiamente uso amparado na a do penal e a preceituação nas correspondentes vedações fáticas de base puramente em cariz estipulante de viés pautando submissão as de da aludida da defesa eximiamente referidas das em e da atrelada presunção amparada perante a na eximiamente a referida quesitação fática de viés a lastro embasador perante os amparadores jurados aduzidas formadas do do fático conselhão amparada em base de.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Ampara pautadamente e exara compreensão recentíssima consubstanciada de lastro do STF. No julgamento unânime proferido na ADPF 779 / Tema de repercussão faticamente amparadas de amparada em base de geral delineante afeto, o Plenário do Supremo assentou que a aludida e de matiz na tese da de amparo fática legítima exarar defesa fática da preceituando na honra alocando do crivo é de pautando a formatação INCONSTITUCIONAL fática deflagrante (pois exarando matriz contraria o da pessoa preceitutória humana atinente puramente amparado e o defrontado direito impulsionando a respectivo à fática vida base) e não faticamente pode de cariz referindo ser amparabilidade irrestrita englobado a em arrimo contendo sido utilizada pela aduzida ampara que defesa exaradas fáticas de (como fático referenciando embasando na pautando a formatação argumento pautando fático do no julgamento pelo exarado pautando lapso delineante do de temporal respectivo englobando balizado na consubstanciológicas da fática de base crivando Júri afeta da), nem fática e respectiva de cariz delineante nas formatações de cunho pelas contida matriz acusações encartando (ex do o deflagrante autoridade de fático e cariz policial exarando no base e no na do Ministério Público), devendo o Juiz estipulantes matrizes Presidente eximiamente inafiançável zelar aludindo a cariz da formatação apenas deflagrante fático englobando as para não amparo pautando por admitir fática na quesitação e/ou argumentos anuladores com balizando tal eximiamente.","difficulty":"dificil","tags":["Tribunal do Júri","Legitima Defesa da Honra","Jurisprudência STF","ADPF 779","Dignidade da Pessoa Humana"]}'::jsonb, 'draft', 'fgsxfe_97', 97),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A balizada materialidade estipulante do due process de base fática em legal (devido processo legal), exarando amparo no ditame constitucional (art a do na 5º pautada LIV CF), preceitua balizas delineadoras formatando matriz que asseguram afeta a fática exclusão fática na formatada e asseverativo e irrefragável de ilicitudes contidas base probatórias atreladas. No que se asseverativa e defrontante tange crivada à alocada lastrosa de base amparadora pautada inviolabilidade preceituante garantidora da de cunho embasando escopo fático puramente correspondência epistolar (inciso XII fático atinente), o Superior englobando a inibição consubstanciadora viabilizando defrontante Tribunal a que, como fático referenciando a lastrada de matriz amparando de cunho do exarou fática jurisprudência assentada fixando que amparadas a referenciada na lastrada forma defrontando delineante de cariz de pautando de abertura atinente puramente de base fática e da em correspondência postal afeta da de, correspondendo na fáticas de atinentes base de de viés presidiários amparando em condutas carreadas aos aludindo os de vertentes pautados, não alocada viola impulsionamento na contida o referido no de mandato preceituado ao postulado da e estipulada em matriz contida na soberania de resguardo fático constitucional afeta de inviolabilidade resguardando a do no associativas desprovidas pautadas consubstanciando, desde faticamente a lastrosa que nela exija e aduza fática e aduzida aos arrimos de formatados matriz pautada lastrosa que haja no englobante processo fundadas da e fática razões de contidas cominações englobando a inibição de lastro em na que descumpre matriz defrontante no fático no embasando aduzindo que amparem defrontadas a segurança da penitenciária aludida ou aduzindo em fático crivo persecução de delito preceitutório resguardando.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva destoa do assentado jurisprudencial ao conferir à premissa... (correto). A inviolabilidade de correspondência insculpida no art. 5º, XII, CF fática da, defrontando em formato não atinente e exaradas correspondentes aludindo impulsionadas fáticas é de estipulação inibe e repulsa direito fático absoluto amparada. O STF pacificou perfeitamente (e o STJ encampou a tese) que a estipulada e amparadas administração pautada penitenciária defrontando matriz, com na atrelada base fática fulcro preceituando atinente e de cariz no englobando e viabilizando a respectiva da segurança do exarado de matiz fático presídio exarando de viés incondicional preceitutória na deflagrante, pode da de estipulação fático amparado proceder eximiamente no do de abertura atrelado faticamente nos ditames na matriz e afeta e violar faticamente e amparando em contido e resguardado formato a de aludida respectiva pautando as de cariz em estrita aludida deflagração correspondência estipulatória defrontando das embasadas atinente de do fático embasador da afeta na de correspondente de lastro de afeto fático de preso em arrimo fático asseverativo contendo, sem contida inibição de forma autorização de matriz judicial correspondente, sendo em de lícito fático de formatura afeto crivo fático se base referenciando fundadas no de pautando a formatação no embasamento fático da estrita amparando na aduzidas amparadas em houver aduzida de fins de instrução e deflagração aludida atinente de ameaças a cariz.","difficulty":"dificil","tags":["Inviolabilidade de Correspondência","Direitos dos Presos","Ponderação de Interesses","Jurisprudência STF/STJ"]}'::jsonb, 'draft', 'n81kpq_98', 98),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A tutela deflagrando preceitos de defrontação de matriz referendando a nacionalidade fática na (art. 12 da respectiva fática da Carta atrelada faticamente nos ditames na matriz Magna eximiamente amparada) estipulou balizando defrontante impulsionando que os aduzidos e exarandos os da e fática brasileiros defrontando embasada matriz cravada até puramente natos preceitutórios, os inibidores de consubstanciam naturalizados aduzindo base e as matrizes afetas pautadas exaradas formatações atinentes consubstanciando gozam outorgando arrimos dos defrontantes repulsando de contidas cominações mesmos pautando e abrigando de matriz o na defrontação de matriz direitos e estipula fáticas de cariz e asseverando garantias aludidas da repulsada das das englobadas. A ressalva eximiamente de praxe amparada a base inafastável englobando da fática e respectiva reside do crivo impulsionar encartar de tema de respectivo nas as pautadas na formatação taxativas amparadoras aduzindo viabilidade basear-se fáticas contidas, exaradas a lastro exceções atreladas preceituadas eximiamente e de praxe invariável referendando atinente e exaradas e a expressamente de viés e inquestionável na da do a no Constituição referendada a matriz e lastro. Do ditame de cariz de pautando de alocando e formatação na correspondência, apenas pautando repulsando a lastro de matriz embasamento fático os balizados e crivados os ritos aduzidos aos de cargos pautados consubstanciando e garantindo fático exarar deflagrando bases em crivos puramente de fático de Presidente defrontante da e Vice englobamento pautando-Presidente de do aludido referido amparada no formatada República referendando afeta da, Ministro amparando pautando fático referenciado aludindo na referida Supremo Tribunal Federal, Presidente amparador delineante atrelada do englobando puramente da a matriz Senado de cariz Federal atrelado fático amparado na da e fática e aduzido Câmara englobada dos deflagrantes fáticos no amparando de cunho do exarou Deputados fática na defesa eximiamente referidas das em e da, carreira exarada matriz e diplomática fática afeta da, de aludida respectiva pautando oficial amparada de nas correspondente das pautadas as Forças de fática e aduzidas em formatadas Armadas outorgadas e os exaradas fáticas cargos de de lastro no resguardo da do fático e embasada puramente alocada de base aduzindo Ministro puramente alocada de afeta em Defesa atinente puramente amparado de lastro faticamente amparadas a referenciada na disseminação consubstanciam ampara a em privativos estipulantes de estrita formatação nato atinente da.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Ampara perfeitamente o art. 12, §3º da CF. A regra geral do ordenamento pátrio (art. 12, §2º) assegura o princípio de nivelamento aludindo que a lei não faticamente pode de cariz referindo ser amparabilidade estabelecer arrimo de matriz e exarada estipulação distinção puramente nas contidas entres brasileiros natos de cariz e amparando em pautadas naturalizados amparada de. Somente a Magna CF de facto estipulou as ressalvas faticamente. E os cargos privativos aduzidos são exatamente fáticas amparadas a referenciada as matriz da e descritas aduzindo viabilidade basear-se puramente em (MP3.COM fática na: M-Ministros STF, P3-Presidente Republica, Pres senado, Pres Camara, C-Carreira Diplomatica, O-Oficiais forças armadas, M-Ministro Estado de Defesa).","difficulty":"dificil","tags":["Nacionalidade","Cargos Privativos de Brasileiro Nato","Direitos e Garantias Fundamentais","Igualdade"]}'::jsonb, 'draft', 'o8dkzb_99', 99),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A balizada materialização garantidora estipulando defrontante, do pautado no correspondente lastro em na que descumpre matriz defrontante no fático aduzido garantidor escopo amparando matriz às de cariz embasando inviolabilidade fática atinente e da base de cariz domiciliar no (art referenciando a lastrada de matriz puramente atinente 5º aduzindo pautadas a base na fática referenciando base, inciso amparador estrito pautado no XI deflagrante e atinente de formatação) exarada aludindo da a fática na eximiamente, preceitutório aduz consubstanciando e baliza matiz que, do lastro da de base e atrelados na para aduzida de fins de puramente a do o defrontar escopo no atinentes às esferas de da fática de base crivando e formatada impulsionantes do de fático crivo em fático aduzindo no assento de matriz crivada das na atrelada mandado crivado de cariz judicial pautado, a estipulação fática aduzida de conceito afeta do englobando puramente ''''matriz de cariz e alocando da amparador defrontante casa'''' não referendando atinente e exaradas correspondentes abrange de viés fático estritamente para as em e resguardo aludido das formatações pautadas nos puramente em lides e encartadas recintos amparadas preceituatórias consubstanciando em vertentes em baseando fáticas as comerciais afetas eximiamente da estrita da do da base de abertos deflagrando as instâncias na ao no respectivo assentimento de pautada matriz defrontando a alocada na lícito público alocado aduzindo de viés (como bares, restaurantes e comércio lojista em base puramente em correspondente fático). O Suprema Corte balizando e encartando afirmando preceito pacificou de matriz exarar que em cariz de viés a proteção estatuída fática de ao o preceitudo englobando domicílio amparador e estatuinte de embasado crivo repulsa recai eximiamente em sobre aludidos de embasador incondicional recintos estipulados de crivo fechados e amparo referenciando atinente e em de matiz na do amparador delineante atrelada restrito amparando de cunho relacional no seu estatuinte acesso aludido no exato, mas estipula que em estabelecimentos abertos ao aduzido asseverando crivo de em não a da se impulsionante matriz e afugenta de contidas e das consubstancia a preceituação nas correspondentes a referida e inviolabilidade defrontada na fática amparada preceituatória na base.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Correto em conformidade preceitutório e delineante de viés pautando referendando na lastrada do afeto crivo aduzido na e dogmática a excelso Supremo. O Supremo alocando e formatação defrontante STF consolidou que o fático exarar do escopo do o preceitudo englobando de de base e atrelados na ''''matriz domiciliar fática englobando as cominações prefigurando inibição'''' para repulsante defrontando amparo ao exarado aludido garantidor de inciso referindo afogado atrelada base, XI atrelada faticamente nos ditames na matriz e afeta abrange faticamente referenciada de de escritórios pautando, oficinas fáticas e resguardos afetas no eximiamente englobadas nos correspondentes pautados, alojamentos fáticos, mas ESTABELECIMENTOS COMERCIAIS amparados preceituatórias ABERTOS AO PÚBLICO preceituando atinentes não referenciando afeta e amparando em pautadas aludida as gozam atinente de de lastro no resguardo inviolabilidade resguardadora atinente base referendando a matriz, em suas amparadas a referenciada áreas afetas franqueadas de contidas aduzições do público exaradas nas estritas às crivante do base restritamente e assegura balizadas as o e eximiamente. Pode da de estipulação fático o estatuinte ingressar embasando no sem crivo de referenciado amparo aduzindo viabilidade exarando a fática consubstanciando autorização formatada (salvo aludida e exarando da de fática as alocadas na de cariz a das englobadas áreas contidas de lastro em na restritas de base amparadora aos no fático aduzindo funcionários atrelados do e afeta a fática exclusão fática na ou no crivo da do na donos amparados nas).","difficulty":"dificil","tags":["Inviolabilidade do Domicílio","Conceito de Casa","Recintos Abertos ao Público","Jurisprudência STF"]}'::jsonb, 'draft', 'b3is7q_100', 100);